shellCommands.command:
cd /workspace && (PORT=3111 npx next start -p 3111 >/tmp/next.log 2>&1 &) && sleep 4 && echo "--- HOME ---" && curl -s -o /tmp/home.html -w "status=%{http_code}
" http://localhost:3111/ && grep -o "Currently reading\|Nothing right now\|Finished\|Nothing yet\|Add a book" /tmp/home.html | sort -u && echo "--- 404 book ---" && curl -s -o /dev/null -w "status=%{http_code}
" http://localhost:3111/books/does-not-exist && echo "--- new page ---" && curl -s -o /tmp/new.html -w "status=%{http_code}
" http://localhost:3111/books/new && grep -o "Add a book" /tmp/new.html | head -1
